import express from 'express';

const app = express();
app.use(express.json());

let livros = [
  { id: 1, titulo: 'Dom Casmurro' },
  { id: 2, titulo: 'O Cortiço' },
  { id: 3, titulo: 'Memórias Póstumas' },
  { id: 4, titulo: 'Grande Sertão' },
];

app.get('/api/livros', (req, res) => {
  // 1. Paginação lida da query (chegou como texto; viramos número).
  const pagina = Number(req.query.pagina ?? 1);
  const itensPorPagina = Number(req.query.itens ?? 2);
  const inicio = (pagina - 1) * itensPorPagina;
  const itens = livros.slice(inicio, inicio + itensPorPagina);

  // 2. A resposta diz o total e ONDE continuar (HATEOAS leve).
  res.json({
    itens,
    total: livros.length,
    pagina,
    links: {
      proxima:
        inicio + itensPorPagina < livros.length
          ? '/api/livros?pagina=' + (pagina + 1) + '&itens=' + itensPorPagina
          : null,
    },
  });
});

app.get('/api/livros/:id', (req, res) => {
  const livro = livros.find((l) => l.id === Number(req.params.id));
  if (!livro) return res.status(404).json({ erro: 'livro não encontrado' });
  res.json({ livro, links: { self: '/api/livros/' + livro.id } });
});

app.post('/api/livros', (req, res) => {
  // 3. Recurso criado: 201 + Location diz onde o recurso novo mora.
  const livro = { id: livros.length + 1, titulo: req.body.titulo };
  livros = [...livros, livro];
  res
    .status(201)
    .location('/api/livros/' + livro.id)
    .json({ livro, links: { self: '/api/livros/' + livro.id } });
});

app.listen(3000);
